-- Starter pages for the "main" publication (Ass to Mouth): About, Advertise,
-- Contact, Terms, Privacy and Legal. Editable in Admin -> Pages. Terms and
-- Privacy are holding text until the legal review. Skips any slug that already
-- exists, and does nothing where "main" doesn't exist (fresh or test databases).
INSERT INTO "site_pages" ("id", "publication_id", "slug", "title", "standfirst", "body", "footer_group", "position", "contact_topic")
SELECT gen_random_uuid()::text, p."id", v.slug, v.title, v.standfirst, v.body, v.footer_group, v.position, v.contact_topic
FROM "publications" p
CROSS JOIN (VALUES
  ('about', 'About us', 'An independent magazine about adult film and the culture around it.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ass to Mouth is an editorial magazine for adults who take adult entertainment seriously. We publish reviews, features, interviews and industry news, written by people who know the genre and care about doing it justice."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We''re independent. Our reviews are our own opinion, and sponsored content is always labelled as sponsored."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Everyone featured on the site was 18 or older at the time of production. Only adults are allowed to use this site."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Get in touch"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Story tip, correction or feedback? "}, {"type": "text", "text": "Send us a message", "marks": [{"type": "link", "attrs": {"href": "/contact"}}]}, {"type": "text", "text": ". Interested in reaching our readers? See "}, {"type": "text", "text": "Advertise with us", "marks": [{"type": "link", "attrs": {"href": "/advertise"}}]}, {"type": "text", "text": "."}]}]}'::jsonb, 'about', 1, NULL),
  ('advertise', 'Advertise with us', 'Reach an engaged adult audience with display, sponsored and partner placements.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "We work with studios, platforms and brands in the adult industry that want to reach readers who are interested in what they make."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What we offer"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Display banners across the site, sponsored reviews and features (always clearly labelled), and partner placements on our homepage."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tell us a little about your brand and what you''d like to achieve using the form below, and we''ll send you our media kit and rates."}]}]}'::jsonb, 'about', 2, 'advertising'),
  ('contact', 'Contact us', 'Questions, story tips, corrections or feedback. We read everything.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Use the form below and we''ll reply by email, usually within a few working days."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "To ask us to remove content, choose “Content removal / DMCA” and include the address of the page and why it should be removed."}]}]}'::jsonb, 'about', 3, 'general'),
  ('terms', 'Terms of use', NULL, '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "We''re finishing our terms of use and will publish it here shortly."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you have a question in the meantime, "}, {"type": "text", "text": "contact us", "marks": [{"type": "link", "attrs": {"href": "/contact"}}]}, {"type": "text", "text": "."}]}]}'::jsonb, 'legal', 1, NULL),
  ('privacy', 'Privacy policy', NULL, '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "We''re finishing our privacy policy and will publish it here shortly."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you have a question in the meantime, "}, {"type": "text", "text": "contact us", "marks": [{"type": "link", "attrs": {"href": "/contact"}}]}, {"type": "text", "text": "."}]}]}'::jsonb, 'legal', 2, NULL),
  ('legal', 'Legal information', NULL, '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "All performers appearing in any content on this site were 18 years of age or older at the time of production."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Our full legal notices are being finalised and will be published here shortly."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Content removal"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "If you believe content on this site infringes your rights, or you appear in content without your consent, use the form below and choose “Content removal / DMCA”. Include the address of the page. We act on valid requests promptly."}]}]}'::jsonb, 'legal', 3, 'removal')
) AS v(slug, title, standfirst, body, footer_group, position, contact_topic)
WHERE p."slug" = 'main'
ON CONFLICT ("publication_id", "slug") DO NOTHING;
